  "aspectos": {
    "entidade": {
      "estado": "sustentado",
      "fonte_ids": ["N.T_ASSEMBLY"],
      "justificativa": "N.T_ASSEMBLY identifica T_ASSEMBLY como Montagem do protótipo."
    },
    "alvo": {
      "estado": "sustentado",
      "fonte_ids": ["N.T_ASSEMBLY", "E016"],
      "justificativa": "N.T_ASSEMBLY documenta a atividade T_ASSEMBLY; E016 registra que C_MOTOR é requisito para essa atividade."
    },
    "atributo": {
      "estado": "sustentado",
      "fonte_ids": ["LOCAL.ASSEMBLY", "N.T_ASSEMBLY"],
      "justificativa": "Ambas as fontes identificam a duração da montagem como atributo pertinente."
    },
    "unidade": {
      "estado": "sustentado",
      "fonte_ids": ["N.T_ASSEMBLY"],
      "justificativa": "N.T_ASSEMBLY expressa a duração em dias corridos."
    },
    "valor": {
      "estado": "sustentado",
      "fonte_ids": ["LOCAL.ASSEMBLY", "N.T_ASSEMBLY", "CHANGE.D08"],
      "justificativa": "N.T_ASSEMBLY e LOCAL.ASSEMBLY registram 5 dias; CHANGE.D08 informa que as demais durações são mantidas e que não há alteração técnica da montagem."
    },
    "condicoes": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D08", "LOCAL.ASSEMBLY"],
      "justificativa": "A mudança relatada é de disponibilidade contratada do fornecedor, sem alteração técnica da montagem. LOCAL.ASSEMBLY determina que mudanças exclusivamente de entrega ou preço mantêm a duração e que somente uma alteração técnica explícita pode substituí-la."
    },
    "escopo": {
      "estado": "sustentado",
      "fonte_ids": ["CHANGE.D08"],
      "justificativa": "CHANGE.D08 limita o fato ao prospectivo desde D0 e ao universo sintético Alfa v1, compatível com o escopo do evento e do projeto indicado no pacote."
    }
  },
  "fontes_examinadas": ["CHANGE.D08", "E016", "LOCAL.ASSEMBLY", "N.T_ASSEMBLY"],
  "justificativa": "A proposta confirma a manutenção da duração local de T_ASSEMBLY. As fontes originais sustentam a entidade, o alvo, o atributo, a unidade e o valor de 5 dias corridos; o relato e a regra local sustentam as condições de aplicação. E016, citado pela proposta, confirma a relação de requisito entre o motor e a montagem, sem alterar a duração local.",
  "suporte_ausente": []
}
